def next_smallest_palindrome(num):
    if str(num) == str(num)[::-1]:
        return None

    while True:
        num = int(str(num)[0] + str(num)[1])

        # Check if the new number is still a palindrome
        if str(num) == str(num)[::-1]:
            return num

